# ==============================================================================# 092_LEAD_QUALIFICATION_ENGINE.py## IOTEC LEAD QUALIFICATION ENGINE## Missão:# Avaliar automaticamente o potencial comercial das empresas.# ==============================================================================from __future__ import annotationsimport sqlite3import hashlibimport jsonfrom pathlib import Pathfrom datetime import datetimeDB = Path("iotec.db")class LeadQualificationEngine:    def __init__(self):        self.conn = sqlite3.connect(DB)        self.conn.row_factory = sqlite3.Row        self.conn.execute("""        CREATE TABLE IF NOT EXISTS commercial_leads(            id INTEGER PRIMARY KEY AUTOINCREMENT,            company_uuid TEXT UNIQUE,            lead_score INTEGER,            lead_grade TEXT,            priority TEXT,            recommendation TEXT,            qualified_at TEXT,            metadata TEXT,            hash TEXT        )        """)        self.conn.commit()    # -----------------------------------------------------------------    def _sha(self, obj):        raw = json.dumps(            obj,            ensure_ascii=False,            sort_keys=True        )        return hashlib.sha256(raw.encode()).hexdigest()    # -----------------------------------------------------------------    def calculate_score(self, company, profile):        score = 0        if company["canonical_name"]:            score += 20        if company["cnpj"]:            score += 25        if profile["website"]:            score += 15        if profile["email"]:            score += 15        if profile["phone"]:            score += 10        if company["city"]:            score += 5        if company["segment"]:            score += 10        return min(score, 100)    # -----------------------------------------------------------------    def classify(self, score):        if score >= 90:            return "A", "CRÍTICA"        if score >= 75:            return "B", "ALTA"        if score >= 50:            return "C", "MÉDIA"        return "D", "BAIXA"    # -----------------------------------------------------------------    def process_all(self):        empresas = self.conn.execute("""            SELECT m.*, p.*            FROM commercial_master_company m            JOIN commercial_company_profile p            ON m.company_uuid = p.company_uuid        """).fetchall()        total = 0        for row in empresas:            r = dict(row)            score = self.calculate_score(r, r)            grade, prioridade = self.classify(score)            lead = {                "company_uuid": r["company_uuid"],                "lead_score": score,                "lead_grade": grade,                "priority": prioridade,                "recommendation":                    "Prosseguir abordagem comercial"                    if score >= 75                    else "Necessita enriquecimento",                "qualified_at": datetime.utcnow().isoformat(),                "metadata": {                    "origin":"092_LEAD_QUALIFICATION_ENGINE"                }            }            assinatura = self._sha(lead)            self.conn.execute("""            INSERT OR REPLACE INTO commercial_leads(                company_uuid,                lead_score,                lead_grade,                priority,                recommendation,                qualified_at,                metadata,                hash            )            VALUES(?,?,?,?,?,?,?,?)            """,(                lead["company_uuid"],                lead["lead_score"],                lead["lead_grade"],                lead["priority"],                lead["recommendation"],                lead["qualified_at"],                json.dumps(lead["metadata"], ensure_ascii=False),                assinatura            ))            total += 1        self.conn.commit()        return total# ==============================================================================# TESTE# ==============================================================================if __name__ == "__main__":    engine = LeadQualificationEngine()    total = engine.process_all()    print("="*80)    print("LEAD QUALIFICATION")    print("="*80)    print(f"Leads qualificados : {total}")    print("Status             : SUCCESS")    print("="*80)